def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all prime factors with multiplicity
    prime_factors = []
    n = a
    divisor = 2
    while n > 1 and divisor <= n:
        while n % divisor == 0 and is_prime(divisor):
            prime_factors.append(divisor)
            n //= divisor
        divisor += 1

    return len(prime_factors) == 3
```

