def is_samepatterns(patterns, words):
    # Lists must be of the same length
    if len(patterns) != len(words):
        return False

    mapping = {}
    seen_words = set()

    for p, w in zip(patterns, words):
        # Check if pattern is already mapped to a specific word
        if p in mapping:
            if mapping[p] != w:
                return False
        else:
            # New pattern encountered
            # Check if this word was already assigned to a different pattern
            if w in seen_words:
                return False

            mapping[p] = w
            seen_words.add(w)

    return True

# Verification test case
assert is_samepatterns(["red","green","green"], ["a", "b", "b"])==True
```

