def max_product(arr):
    if not arr:
        return 0

    n = len(arr)
    dp = [arr[0]] * n

    # Compute DP table where dp[i] is the maximum product of an increasing subsequence ending at index i
    for i in range(1, n):
        max_prev = -float('inf')
        for j in range(i):
            if arr[j] < arr[i]:
                max_prev = max(max_prev, dp[j])
        dp[i] = max_prev * arr[i] if max_prev != -float('inf') else arr[i]

    return max(dp)
```

